<PackageInfo>

## Features

- Utilities for creating trigger-based combobox functionality
- Configurable trigger characters and patterns
- Keyboard navigation and selection handling

</PackageInfo>

## Create a Combobox Plugin

<Steps>

### Installation

```bash
npm install platejs @tanstack/react-virtual
```

### Create Input Plugin

First, create an input plugin that will be inserted when the trigger is activated:

```tsx
import { defineBasePlugin } from 'platejs';

const TagInputPlugin = defineBasePlugin('tagInput', {
  editOnly: true,
  schema: { element: { type: 'tag_input', void: 'inline' } },
});
```

### Create Main Plugin

Create your main plugin with trigger metadata:

```tsx
import { defineBasePlugin } from 'platejs';
import type { TriggerComboboxPluginState } from 'platejs/combobox';

export type TagPluginState = TriggerComboboxPluginState;

const initialState: TagPluginState = {
  trigger: '#',
  triggerPreviousCharPattern: /^\s?$/,
  createComboboxInput: () => ({
    children: [{ text: '' }],
    type: 'tag_input',
  }),
};

export const TagPlugin = defineBasePlugin('tag', {
  dependencies: [TagInputPlugin],
  initialState,
  schema: { element: { void: 'inline' } },
});
```

- `schema.element`: Defines the plugin's element model behavior
- `schema.element.void: 'inline'`: Makes the tag an inline void and prevents editing inside it
- `initialState.trigger`: Character that triggers the combobox (in this case `#`)
- `initialState.triggerPreviousCharPattern`: RegExp pattern that must match the character before the trigger. `/^\s?$/` allows the trigger at the start of a line or after whitespace
- `initialState.createComboboxInput`: Function that creates the input element node when the trigger is activated

### Create Component

Create the input element component using `InlineCombobox`:

```tsx
import {
  PlateElement,
  useEditor,
  useEditorFocused,
  useEditorReadOnly,
  useElementSelected,
} from 'platejs/react';
import {
  InlineCombobox,
  InlineComboboxContent,
  InlineComboboxEmpty,
  InlineComboboxInput,
  InlineComboboxItem,
} from '@/components/editor/inline-combobox';
import { cn } from '@/lib/utils';

const tags = [
  { id: 'frontend', name: 'Frontend', color: 'blue' },
  { id: 'backend', name: 'Backend', color: 'green' },
  { id: 'design', name: 'Design', color: 'purple' },
  { id: 'urgent', name: 'Urgent', color: 'red' },
];

export function TagInputElement({ element, ...props }) {
  const editor = useEditor();

  return (
    <PlateElement as="span" {...props}>
      <InlineCombobox element={element} trigger="#">
        <InlineComboboxInput />
        <InlineComboboxContent>
          <InlineComboboxEmpty>No tags found</InlineComboboxEmpty>
          {tags.map((tag) => (
            <InlineComboboxItem
              key={tag.id}
              value={tag.name}
              onClick={() => {
                editor.update((tx) => {
                  tx.nodes.insert({
                    children: [{ text: tag.name }],
                    tagId: tag.id,
                    type: 'tag',
                  });
                });
              }}
            >
              <span 
                className={`w-3 h-3 rounded-full bg-${tag.color}-500 mr-2`}
              />
              #{tag.name}
            </InlineComboboxItem>
          ))}
        </InlineComboboxContent>
      </InlineCombobox>
      {props.children}
    </PlateElement>
  );
}

export function TagElement({ element, ...props }) {
  const selected = useElementSelected();
  const focused = useEditorFocused();
  const readOnly = useEditorReadOnly();

  return (
    <PlateElement
      {...props}
      className={cn(
        'inline-block rounded-md bg-primary/10 px-1.5 py-0.5 align-baseline text-sm font-medium text-primary',
        !readOnly && 'cursor-pointer',
        selected && focused && 'ring-2 ring-ring'
      )}
      attributes={{
        ...props.attributes,
        contentEditable: false,
        'data-plite-value': element.value,
      }}
    >
      #{element.value}
      {props.children}
    </PlateElement>
  );
}
```

### Add to Editor

```tsx
import { PLUGINS } from 'platejs';
import { createEditor } from 'platejs/react';
import { TagPlugin, TagInputPlugin } from './tag-plugin';
import { TagElement, TagInputElement } from './tag-components';

const editor = createEditor({
  plugins: [
    // ...otherPlugins,
    TagPlugin.configure({
      component: TagElement,
      initialState: {
        triggerQuery: (editor) => {
          // Disable in code blocks
          const codeBlock = editor.plugin(PLUGINS.codeBlock);

          return (
            !codeBlock.installed ||
            !editor.read.nodes.some({ type: codeBlock.schema.type })
          );
        },
      },
    }),
    TagInputPlugin.configure({ component: TagInputElement }),
  ],
});
```

- `initialState.triggerQuery`: Optional function to conditionally enable/disable the trigger based on editor state

